import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.formrecognizer import DocumentAnalysisClient

def extract_invoice_data(file_path: str) -> dict:
    """
    Extracts vendor, date, total, and line-item fields from an invoice
    using Azure AI Document Intelligence's prebuilt invoice model.

    Args:
        file_path: The local path to the invoice file (PDF, PNG, JPEG, etc.).

    Returns:
        A dictionary containing the extracted invoice data.
    """
    try:
        endpoint = os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
        key = os.environ["AZURE_FORM_RECOGNIZER_KEY"]
    except KeyError:
        raise Exception(
            "Please set the AZURE_FORM_RECOGNIZER_ENDPOINT and "
            "AZURE_FORM_RECOGNIZER_KEY environment variables."
        )

    document_analysis_client = DocumentAnalysisClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(file_path, "rb") as f:
        poller = document_analysis_client.begin_analyze_document(
            "prebuilt-invoice", document=f
        )

    invoices = poller.result()

    # Process the first invoice found in the document
    if not invoices.documents:
        return {}

    invoice = invoices.documents[0]
    extracted_data = {}

    # Extract top-level fields
    vendor = invoice.fields.get("VendorName")
    if vendor:
        extracted_data["vendor"] = vendor.value

    date = invoice.fields.get("InvoiceDate")
    if date:
        extracted_data["date"] = date.value.isoformat() if date.value else None

    total = invoice.fields.get("InvoiceTotal")
    if total:
        extracted_data["total"] = total.value

    # Extract line items
    line_items = []
    items_field = invoice.fields.get("Items")
    if items_field and items_field.value:
        for item in items_field.value:
            item_data = {}
            description = item.value.get("Description")
            if description:
                item_data["description"] = description.value

            quantity = item.value.get("Quantity")
            if quantity:
                item_data["quantity"] = quantity.value

            unit_price = item.value.get("UnitPrice")
            if unit_price:
                item_data["unit_price"] = unit_price.value

            amount = item.value.get("Amount")
            if amount:
                item_data["amount"] = amount.value

            if item_data:
                line_items.append(item_data)

    extracted_data["line_items"] = line_items

    return extracted_data
